import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

/**
 * Expenses Page Test Suite
 *
 * This test suite validates expense categorization features defined in:
 * specs/specifications/expense-categorization.md
 *
 * All tests are traceable to specific requirements using specification IDs (#{#expNx})
 *
 * Initial test: #{#exp1a} - Expenses Tab Navigation
 */

describe('Expenses Page - Navigation and Routing', () => {
	describe('#{#exp1a} Expenses Tab Navigation', () => {
		/**
		 * Requirement: Main navigation must include an "Expenses" tab
		 * Authority: platform
		 * Priority: High
		 *
		 * Acceptance Criteria:
		 * 1. Main navigation must include an "Expenses" tab alongside existing tabs
		 * 2. Tab must be accessible via URL route `/expenses`
		 * 3. Tab must be highlighted when active using consistent navigation styling
		 * 4. Tab must be accessible via keyboard navigation
		 * 5. Clicking tab must load the expenses view without page refresh (SPA behavior)
		 * 6. Tab must show active state when on expenses route or sub-routes
		 * 7. Tab must be visible to authenticated users only
		 */

		it('should have /expenses route accessible', () => {
			// This test verifies that the +page.svelte file exists for the expenses route
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const routeExists = existsSync(routePath);

			expect(routeExists).toBe(true);
		});

		it('should export expenses page metadata', () => {
			// Verify that the page exports metadata for navigation
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');

			if (!existsSync(routePath)) {
				expect.fail('Route file does not exist');
				return;
			}

			const content = readFileSync(routePath, 'utf-8');
			const pageExportsMetadata = content.includes('export const metadata');

			expect(pageExportsMetadata).toBe(true);
		});

		it('should render expenses tab in main navigation', () => {
			// This test verifies that +layout.svelte includes the Expenses tab
			const layoutPath = join(process.cwd(), 'src/routes/+layout.svelte');
			const content = readFileSync(layoutPath, 'utf-8');

			// Check for Expenses link with proper href
			const navigationHasExpensesTab =
				content.includes('/expenses') && content.includes('Expenses');

			expect(navigationHasExpensesTab).toBe(true);
		});

		it('should preserve date filters when navigating to expenses tab', () => {
			// #{#sdf3a} integration - date filters should persist
			// This test verifies the preserveFilters() function works for /expenses
			const layoutPath = join(process.cwd(), 'src/routes/+layout.svelte');
			const content = readFileSync(layoutPath, 'utf-8');

			// Verify preserveFilters is called for /expenses
			const preservesFilters = content.includes("preserveFilters('/expenses')");

			expect(preservesFilters).toBe(true);
		});

		it('should show active state when on /expenses route', () => {
			// Test that the Expenses tab shows active styling when on the route
			// This is verified by checking for aria-current or CSS class
			const layoutPath = join(process.cwd(), 'src/routes/+layout.svelte');
			const content = readFileSync(layoutPath, 'utf-8');

			// Check for active state indicators (aria-current or class:font-semibold)
			const expensesSection = content.substring(content.indexOf('/expenses'));
			const showsActiveState =
				expensesSection.includes('aria-current') || expensesSection.includes('class:');

			expect(showsActiveState).toBe(true);
		});

		it('should be keyboard accessible with Tab key navigation', () => {
			// Verify the expenses tab link is in the tab order
			// Links are keyboard accessible by default in HTML
			const layoutPath = join(process.cwd(), 'src/routes/+layout.svelte');
			const content = readFileSync(layoutPath, 'utf-8');

			// Check that it's a proper <a> tag (keyboard accessible by default)
			const hasExpensesLink = content.includes('<a') && content.includes('/expenses');

			expect(hasExpensesLink).toBe(true);
		});

		it('should only be visible to authenticated users', () => {
			// Verify that the page checks authentication
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for authentication check (supabase.auth.getSession)
			const requiresAuthentication =
				content.includes('supabase.auth.getSession') || content.includes('session');

			expect(requiresAuthentication).toBe(true);
		});
	});

	describe('Expenses Page - Content Structure', () => {
		it('should render page title', () => {
			// Basic page structure test - check for h1 title
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			const hasTitleElement = content.includes('<h1') && content.includes('Expenses');

			expect(hasTitleElement).toBe(true);
		});

		it('should render empty state when no expenses exist', () => {
			// Verify empty state UI is shown when user has no expenses
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for empty state message
			const showsEmptyState = content.includes('No expenses') || content.includes('no expenses');

			expect(showsEmptyState).toBe(true);
		});

		it('should render expenses table structure', () => {
			// Verify basic table layout exists (will be detailed in #{#exp9a})
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for table structure
			const hasTableStructure =
				content.includes('<table') && content.includes('<thead') && content.includes('<tbody');

			expect(hasTableStructure).toBe(true);
		});
	});

	describe('#{#exp9a} Expense Table Layout', () => {
		/**
		 * Requirement: Expense table must display specific columns with proper formatting
		 * Authority: developer
		 * Priority: High
		 *
		 * Acceptance Criteria:
		 * 1. Table must include columns: Checkbox, Date, Merchant, Amount, Category, Receipt
		 * 2. Date must be formatted as YYYY-MM-DD or user locale preference
		 * 3. Amount must be formatted with currency symbol and 2 decimal places
		 * 4. Category column must show category chip (clickable for reassignment)
		 * 5. Receipt column must show thumbnail or "View" link to receipt image
		 * 6. Table must be sortable by Date, Merchant, Amount (ascending/descending)
		 * 7. Default sort: Date descending (newest first)
		 * 8. Table must show empty state when no expenses exist: "No expenses found"
		 * 9. Table must be responsive (stack on mobile or horizontal scroll)
		 */

		it('should include Checkbox column in table header', () => {
			// #{#exp9a} Criterion 1: Table must include Checkbox column
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for checkbox column in header
			const hasCheckboxHeader =
				content.includes('<th') &&
				(content.includes('Checkbox') ||
					content.includes('Select') ||
					content.includes('type="checkbox"'));

			expect(hasCheckboxHeader).toBe(true);
		});

		it('should include Date column in table header', () => {
			// #{#exp9a} Criterion 1: Table must include Date column
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for Date column (flexible to account for sorting elements)
			const hasDateColumn = content.includes('Date') && content.includes('<th');

			expect(hasDateColumn).toBe(true);
		});

		it('should include Merchant column in table header', () => {
			// #{#exp9a} Criterion 1: Table must include Merchant column
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for Merchant column (flexible to account for sorting elements)
			const hasMerchantColumn = content.includes('Merchant') && content.includes('<th');

			expect(hasMerchantColumn).toBe(true);
		});

		it('should include Amount column in table header', () => {
			// #{#exp9a} Criterion 1: Table must include Amount column
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for Amount column (flexible to account for sorting elements)
			const hasAmountColumn = content.includes('Amount') && content.includes('<th');

			expect(hasAmountColumn).toBe(true);
		});

		it('should include Category column in table header', () => {
			// #{#exp9a} Criterion 1: Table must include Category column
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for Category column
			const hasCategoryColumn = content.includes('>Category<');

			expect(hasCategoryColumn).toBe(true);
		});

		it('should include Receipt column in table header', () => {
			// #{#exp9a} Criterion 1: Table must include Receipt column
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for Receipt column
			const hasReceiptColumn = content.includes('>Receipt<');

			expect(hasReceiptColumn).toBe(true);
		});

		it('should format date using formatDate function', () => {
			// #{#exp9a} Criterion 2: Date must be formatted
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for formatDate function
			const hasDateFormatting =
				content.includes('formatDate') && content.includes('transaction_date');

			expect(hasDateFormatting).toBe(true);
		});

		it('should format currency with symbol and decimal places', () => {
			// #{#exp9a} Criterion 3: Amount must be formatted with currency symbol and 2 decimals
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for currency formatting function
			const hasCurrencyFormatting =
				content.includes('formatCurrency') &&
				(content.includes('Intl.NumberFormat') || content.includes('currency'));

			expect(hasCurrencyFormatting).toBe(true);
		});

		it('should display CategoryDropdown component for category assignment', () => {
			// #{#exp9a} Criterion 4: Category column must show clickable category chip
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for CategoryDropdown component
			const hasCategoryDropdown = content.includes('CategoryDropdown');

			expect(hasCategoryDropdown).toBe(true);
		});

		it('should display receipt link or thumbnail in Receipt column', () => {
			// #{#exp9a} Criterion 5: Receipt column must show thumbnail or view link
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for receipt_image_path handling
			const hasReceiptDisplay =
				content.includes('receipt_image_path') &&
				(content.includes('href') || content.includes('img'));

			expect(hasReceiptDisplay).toBe(true);
		});

		it('should have sortable column headers with click handlers', () => {
			// #{#exp9a} Criterion 6: Table must be sortable by Date, Merchant, Amount
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for sort functionality (click handlers or sort state)
			const hasSortingFeature =
				content.includes('sort') || content.includes('onclick') || content.includes('on:click');

			expect(hasSortingFeature).toBe(true);
		});

		it('should sort expenses by date descending by default', () => {
			// #{#exp9a} Criterion 7: Default sort is Date descending (newest first)
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for default sorting logic
			// This could be in SQL query (ORDER BY transaction_date DESC) or JS sorting
			const hasDefaultSort =
				content.includes('DESC') ||
				content.includes('descending') ||
				content.includes('sort') ||
				content.includes('transaction_date');

			expect(hasDefaultSort).toBe(true);
		});

		it('should show "No expenses found" empty state message', () => {
			// #{#exp9a} Criterion 8: Empty state must show specific message
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for exact empty state message
			const hasEmptyStateMessage = content.includes('No expenses found');

			expect(hasEmptyStateMessage).toBe(true);
		});

		it('should have responsive table with overflow-x-auto or mobile stack', () => {
			// #{#exp9a} Criterion 9: Table must be responsive
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for responsive design classes
			const isResponsive =
				content.includes('overflow-x-auto') ||
				content.includes('overflow-auto') ||
				content.includes('responsive') ||
				content.includes('@media');

			expect(isResponsive).toBe(true);
		});

		it('should render checkboxes for each expense row for bulk operations', () => {
			// #{#exp9a} Criterion 1: Checkbox column for selection
			// #{#exp6b} Integration: Support for bulk category assignment
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for checkbox in table body rows (updated to use sortedExpenses)
			const hasRowCheckboxes =
				content.includes('type="checkbox"') &&
				(content.includes('{#each expenses') || content.includes('{#each sortedExpenses'));

			expect(hasRowCheckboxes).toBe(true);
		});

		it('should display expense count summary', () => {
			// Additional UX feature: Show count of expenses
			const routePath = join(process.cwd(), 'src/routes/expenses/+page.svelte');
			const content = readFileSync(routePath, 'utf-8');

			// Check for expense count display
			const hasExpenseCount = content.includes('expenses.length') && content.includes('Showing');

			expect(hasExpenseCount).toBe(true);
		});
	});
});

