import { describe, it, expect } from 'vitest';
import { applySelectionClick, type SelectionState } from './selectionModel';

/**
 * Pure multi-select state machine shared by the list-page tables (RF-03).
 *
 * Modifier semantics (clicks land on the row checkbox; plain row-click is edit):
 *  - plain          → toggle the row, set anchor
 *  - Cmd/Ctrl       → additive toggle, set anchor
 *  - Shift          → union the anchor→row range in the current visible order
 *
 * Tested through the public interface only (ordered ids + state + click → state),
 * so no browser and no component are needed to pin the correctness-critical logic.
 */
const empty: SelectionState = { selected: new Set<string>(), anchorId: null };
const plain = { shiftKey: false, toggleKey: false };

describe('selectionModel', () => {
	it('plain click selects a previously unselected row and anchors it', () => {
		const next = applySelectionClick(['a', 'b', 'c'], empty, 'b', plain);

		expect([...next.selected]).toEqual(['b']);
		expect(next.anchorId).toBe('b');
	});
});

