import { describe, it, expect } from 'vitest';
import {
	applySelectionClick,
	isAllSelected,
	isIndeterminate,
	toggleSelectAll,
	type SelectionState
} from './selectionModel';

/**
 * Pure multi-select state machine shared by the list-page tables (RF-03).
 *
 * Modifier semantics (clicks land on the row checkbox; plain row-click is edit):
 *  - plain          → toggle the row, set anchor
 *  - Cmd/Ctrl       → additive toggle, set anchor
 *  - Shift          → union the anchor→row range in the current visible order
 *
 * Tested through the public interface only (ordered ids + state + click → state),
 * so no browser and no component are needed to pin the correctness-critical logic.
 */
const empty: SelectionState = { selected: new Set<string>(), anchorId: null };
const plain = { shiftKey: false, toggleKey: false };
const shift = { shiftKey: true, toggleKey: false };
const toggle = { shiftKey: false, toggleKey: true };

describe('selectionModel', () => {
	it('plain click selects a previously unselected row and anchors it', () => {
		const next = applySelectionClick(['a', 'b', 'c'], empty, 'b', plain);

		expect([...next.selected]).toEqual(['b']);
		expect(next.anchorId).toBe('b');
	});

	it('plain click deselects an already-selected row and re-anchors it', () => {
		const state: SelectionState = { selected: new Set(['a', 'b']), anchorId: 'a' };

		const next = applySelectionClick(['a', 'b', 'c'], state, 'b', plain);

		expect([...next.selected]).toEqual(['a']);
		expect(next.anchorId).toBe('b');
	});

	it('Shift+click unions the anchor→row range in visible order and keeps the anchor', () => {
		const state: SelectionState = { selected: new Set(['b']), anchorId: 'b' };

		const next = applySelectionClick(['a', 'b', 'c', 'd', 'e'], state, 'd', shift);

		expect([...next.selected].sort()).toEqual(['b', 'c', 'd']);
		expect(next.anchorId).toBe('b');
	});

	it('Shift+click extends the range when the target is above the anchor', () => {
		const state: SelectionState = { selected: new Set(['d']), anchorId: 'd' };

		const next = applySelectionClick(['a', 'b', 'c', 'd', 'e'], state, 'b', shift);

		expect([...next.selected].sort()).toEqual(['b', 'c', 'd']);
		expect(next.anchorId).toBe('d');
	});

	it('Shift range follows the current visible order, not the original order', () => {
		// Rows re-sorted so the visible order is reversed; range must use it.
		const state: SelectionState = { selected: new Set(['e']), anchorId: 'e' };

		const next = applySelectionClick(['e', 'd', 'c', 'b', 'a'], state, 'c', shift);

		expect([...next.selected].sort()).toEqual(['c', 'd', 'e']);
	});

	it('Shift+click degrades to a plain toggle when there is no anchor', () => {
		const next = applySelectionClick(['a', 'b', 'c'], empty, 'b', shift);

		expect([...next.selected]).toEqual(['b']);
		expect(next.anchorId).toBe('b');
	});

	it('Shift+click degrades to a plain toggle when the anchor is no longer visible', () => {
		// Anchor 'x' was filtered out of the current rows.
		const state: SelectionState = { selected: new Set(['a']), anchorId: 'x' };

		const next = applySelectionClick(['a', 'b', 'c'], state, 'c', shift);

		expect([...next.selected].sort()).toEqual(['a', 'c']);
		expect(next.anchorId).toBe('c');
	});

	it('Cmd/Ctrl+click additively toggles without clearing other rows', () => {
		const state: SelectionState = { selected: new Set(['a', 'c']), anchorId: 'a' };

		const next = applySelectionClick(['a', 'b', 'c'], state, 'b', toggle);

		expect([...next.selected].sort()).toEqual(['a', 'b', 'c']);
		expect(next.anchorId).toBe('b');
	});
});

