/**
 * Pure sorting core for the shared list-page table (RF-03).
 *
 * The <DataTable> shell owns which column is active and the direction; these
 * helpers turn a header click into the next sort state and apply an accessor to
 * order the rows. Keeping it pure lets the toggle rules and comparison be
 * unit-tested without a browser.
 */

export type SortDirection = 'asc' | 'desc';

export interface SortState {
	key: string;
	direction: SortDirection;
}

/** A header click: same column flips direction, a new column starts ascending. */
export function nextSortState(current: SortState | null, key: string): SortState {
	if (current && current.key === key) {
		return { key, direction: current.direction === 'asc' ? 'desc' : 'asc' };
	}
	return { key, direction: 'asc' };
}

/** Stable sort of a copy of `rows` by the accessor, in the given direction. */
export function sortRows<Row>(
	rows: Row[],
	sortValue: (row: Row) => string | number,
	direction: SortDirection
): Row[] {
	const factor = direction === 'asc' ? 1 : -1;
	return rows
		.map((row, index) => ({ row, index }))
		.sort((a, b) => {
			const av = sortValue(a.row);
			const bv = sortValue(b.row);
			let cmp: number;
			if (typeof av === 'number' && typeof bv === 'number') {
				cmp = av - bv;
			} else {
				cmp = String(av).localeCompare(String(bv));
			}
			// Stable: fall back to original order on ties (before applying direction).
			return cmp !== 0 ? cmp * factor : a.index - b.index;
		})
		.map((entry) => entry.row);
}

