import { describe, it, expect } from 'vitest';
import { render } from 'vitest-browser-svelte';
import DataTableFixture from './DataTableFixture.svelte';

/**
 * Wiring tests for the <DataTable> shell (RF-03). Correctness of sorting and
 * selection lives in the pure tableSort / selectionModel unit specs; these prove
 * the shell is actually attached to that logic — one thin flow each, no matrices.
 */
const rows = [
	{ id: 'r1', name: 'Beta', amount: 20 },
	{ id: 'r2', name: 'Alpha', amount: 30 },
	{ id: 'r3', name: 'Gamma', amount: 10 }
];

describe('DataTable', () => {
	it('renders column headers and each row cell', async () => {
		const screen = render(DataTableFixture, { rows });

		await expect.element(screen.getByRole('columnheader', { name: /Name/ })).toBeVisible();
		await expect.element(screen.getByText('Beta')).toBeVisible();
		await expect.element(screen.getByText('Alpha')).toBeVisible();
	});

	it('shows the empty snippet when there are no rows', async () => {
		const screen = render(DataTableFixture, { rows: [] });

		await expect.element(screen.getByText('Nothing here')).toBeVisible();
	});

	it('sorts by a sortable column, toggling direction on repeat clicks', async () => {
		const screen = render(DataTableFixture, { rows });
		const nameHeader = screen.getByRole('columnheader', { name: /Name/ });

		await nameHeader.click();
		await expect.element(screen.getByTestId('name').first()).toHaveTextContent('Alpha');

		await nameHeader.click();
		await expect.element(screen.getByTestId('name').first()).toHaveTextContent('Gamma');
	});

	it('opens the row on a plain cell click but not on an interactive cell', async () => {
		const screen = render(DataTableFixture, { rows, withRowClick: true });

		await screen.getByText('Beta').click();
		await expect.element(screen.getByTestId('last-clicked')).toHaveTextContent('row:r1');

		// The actions column is interactive: its click must not open the row.
		await screen.getByRole('button', { name: 'Act' }).first().click();
		await expect.element(screen.getByTestId('last-clicked')).toHaveTextContent('action:r1');
	});

	it('selects a row via its checkbox and extends with Shift', async () => {
		const screen = render(DataTableFixture, { rows, selectable: true });
		const checkboxes = screen.getByRole('checkbox');

		// nth(0) is the header select-all; rows start at nth(1) in visible order.
		await checkboxes.nth(1).click();
		await expect.element(screen.getByTestId('selected')).toHaveTextContent('r1');

		await checkboxes.nth(3).click({ modifiers: ['Shift'] });
		await expect.element(screen.getByTestId('selected')).toHaveTextContent('r1,r2,r3');
	});

	it('select-all header checkbox toggles every row', async () => {
		const screen = render(DataTableFixture, { rows, selectable: true });

		await screen.getByRole('checkbox').first().click();
		await expect.element(screen.getByTestId('selected')).toHaveTextContent('r1,r2,r3');
	});
});

