/**
 * Toggle expense selection for bulk operations
 * #{#exp9a} Criterion 1: Checkbox column for selection
 * #{#exp6b} Bulk category assignment
 */
function toggleExpenseSelection(receiptId: string) {
	const newSelection = new Set(selectedExpenses);
	if (newSelection.has(receiptId)) {
		newSelection.delete(receiptId);
	} else {
		newSelection.add(receiptId);
	}
	selectedExpenses = newSelection;
}

/**
 * Toggle select all expenses
 */
function toggleSelectAll() {
	if (selectedExpenses.size === expenses.length) {
		selectedExpenses = new Set();
	} else {
		selectedExpenses = new Set(expenses.map((e) => e.receipt_id));
	}
}

/**
 * Sort expenses by column
 * #{#exp9a} Criterion 6: Sortable columns
 */
function sortBy(column: 'date' | 'merchant' | 'amount') {
	if (sortColumn === column) {
		// Toggle direction if same column
		sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
	} else {
		// New column, default to descending for date, ascending for others
		sortColumn = column;
		sortDirection = column === 'date' ? 'desc' : 'asc';
	}
}

/**
 * #{#exr1a} Open receipt edit modal when clicking expense row
 * #{#exr1b} Convert Expense to ReceiptRow format for modal
 */
function openReceiptEditModal(expense: Expense) {
	editingExpense = expense;
	editingReceipt = {
		id: expense.receipt_id,
		user_id: session?.user?.id || '',
		merchant_name: expense.merchant_name,
		transaction_date: expense.transaction_date,
		total_amount: expense.total_amount,
		receipt_image_path: expense.receipt_image_path ?? null,
		tax: null,
		currency: expense.currency,
		exchange_rate_to_cad: expense.exchange_rate_to_cad,
		credit_card_name: null,
		credit_card_last_4: null,
		created_at: new Date().toISOString(),
		matched_transaction_id: null,
		suspicious_date: false,
		original_filename: null // #{#ofn1a} display-only; not carried on Expense
	};
	showEditModal = true;
}

/**
 * #{#exr1a} Handle row click events
 * #{#exr2a} Filter clicks on interactive elements
 */
function handleRowClick(event: MouseEvent | KeyboardEvent, expense: Expense) {
	const target = event.target as HTMLElement;

	// Ignore clicks on interactive elements
	if (
		target.closest('input[type="checkbox"]') ||
		target.closest('[data-category-dropdown]') ||
		target.closest('a')
	) {
		return;
	}

	openReceiptEditModal(expense);
}

