function onRowCheckbox(event: MouseEvent, row: Row) {
	event.preventDefault(); // we drive `checked` from selection state
	selection = applySelectionClick(orderedIds, selection, getRowId(row), {
		shiftKey: event.shiftKey,
		toggleKey: event.metaKey || event.ctrlKey
	});
}

function onSelectAll(event: MouseEvent) {
	event.preventDefault();
	selection = toggleSelectAll(orderedIds, selection);
}

input.new_string:
// We don't preventDefault the native toggle: doing so triggers the browser's
// canceled-activation, which reverts `checked` after Svelte set it and leaves the
// box visually out of sync. Instead we let it toggle, then force it to match state
// (state wins — a Shift-range can leave the clicked row's own value unchanged).
function onRowCheckbox(event: MouseEvent, row: Row) {
	const id = getRowId(row);
	selection = applySelectionClick(orderedIds, selection, id, {
		shiftKey: event.shiftKey,
		toggleKey: event.metaKey || event.ctrlKey
	});
	(event.currentTarget as HTMLInputElement).checked = selection.selected.has(id);
}

function onSelectAll(event: MouseEvent) {
	selection = toggleSelectAll(orderedIds, selection);
	(event.currentTarget as HTMLInputElement).checked = isAllSelected(orderedIds, selection.selected);
}

