34			if (align === 'right') return 'text-right';
35			if (align === 'center') return 'text-center';
36			return 'text-left';
37		}
38	
39		let {
40			rows,
41			columns,
42			getRowId,
43			selectable = false,
44			selection = $bindable(emptySelection()),
45			onRowClick,
46			initialSort,
47			empty
48		}: {
49			rows: Row[];
50			columns: Column<Row>[];
51			getRowId: (row: Row) => string;
52			selectable?: boolean;
53			selection?: SelectionState;
54			onRowClick?: (row: Row) => void;
55			initialSort?: SortState;
56			empty: Snippet;
57		} = $props();
58	
59		// initialSort seeds the starting sort only; header clicks own it afterwards.
60		// svelte-ignore state_referenced_locally
61		let sort = $state<SortState | null>(initialSort ?? null);
62	
63		const activeColumn = $derived(sort ? columns.find((c) => c.key === sort!.key) : undefined);
64		const sortedRows = $derived(
65			activeColumn?.sortValue ? sortRows(rows, activeColumn.sortValue, sort!.direction) : rows
66		);
67		const orderedIds = $derived(sortedRows.map(getRowId));
68	
69		const totalColumns = $derived(columns.length + (selectable ? 1 : 0));
70	
71		function ariaSort(col: Column<Row>): 'ascending' | 'descending' | 'none' {
72			if (!col.sortValue || sort?.key !== col.key) return 'none';
73			return sort!.direction === 'asc' ? 'ascending' : 'descending';
74		}
