83		// box visually out of sync. Instead we let it toggle, then force it to match state
84		// (state wins — a Shift-range can leave the clicked row's own value unchanged).
85		function onRowCheckbox(event: MouseEvent, row: Row) {
86			const id = getRowId(row);
