56		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
57		let urlDateFrom = $derived(urlDateFilter.dateFrom);
58		let urlDateTo = $derived(urlDateFilter.dateTo);
59	
60		// Client-side filters - temporary values for inputs
61		let tempFilterDateFrom = $state(readDateFilter($page.url.searchParams).dateFrom);
62		let tempFilterDateTo = $state(readDateFilter($page.url.searchParams).dateTo);
