84		async function deleteReceipt(r: ReceiptRow): Promise<void> {
85			if (!confirm('Delete this receipt? This will remove the record and the stored file.')) return;
86			deleting.add(r.id);
87			// reassign to trigger reactivity for Set updates
88			deleting = new Set(deleting);
89			error = null;
90			try {
91				await ReceiptService.get().delete(r.id, r.receipt_image_path);
92				allReceipts = allReceipts.filter((x) => x.id !== r.id);
93			} catch (e: any) {
94				error = e?.message ?? 'Failed to delete receipt';
95			} finally {
96				deleting.delete(r.id);
97				deleting = new Set(deleting);
98			}
99		}
