	const imageCells = pageContent.match(
		/<td[^>]*>(?:(?!<\/td>)[\s\S])*?receipt_image_path(?:(?!<\/td>)[\s\S])*?<\/td>/g
	);
	expect(imageCells).not.toBeNull();

	for (const cell of imageCells!) {
		// Extract just the opening <td> tag
