it('opens the modal when the image is clicked (image column is not interactive)', () => {
	// The table cell is now rendered by <DataTable>. Clicking the image must open the
	// row's editor, which DataTable does for any non-`interactive` column. So the image
	// column must NOT be marked interactive, and the page must wire onRowClick.
	// (The old "no stopPropagation on the image <td>" concern is subsumed by this.)
	const imageColumnIsPlain =
		/key: 'image'[^}]*cell: imageCell/.test(pageContent) &&
		!/key: 'image'[^}]*interactive/.test(pageContent);
	const opensOnRowClick = pageContent.includes('onRowClick={openEditModal}');

	expect(imageColumnIsPlain).toBe(true);
	expect(opensOnRowClick).toBe(true);
});

