import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';

/**
 * Receipt Image Click Opens Editor Test Suite
 *
 * This test suite validates that clicking receipt image thumbnails on the
 * Receipts page opens the ReceiptEditModal instead of a new browser tab.
 *
 * Specification: specs/specifications/receipt-image-click-opens-editor.md
 *
 * All tests are traceable to specific requirements using specification IDs (#{#ricNx})
 */

describe('Receipt Image Click Opens Editor', () => {
	const receiptsPagePath = join(process.cwd(), 'src/routes/receipts/+page.svelte');
	const pageContent = readFileSync(receiptsPagePath, 'utf-8');

	describe('#{#ric1a} Image Thumbnail Click Opens Edit Modal', () => {
		it('should NOT have target="_blank" links wrapping receipt image thumbnails', () => {
			// The image thumbnail should not be wrapped in an <a target="_blank"> link
			// that opens the image in a new tab. Instead, the row click handler should fire.

			// Find the image cell section — look for the thumbnail img tag
			// Current problematic pattern: <a target="_blank" href=...><img ... alt="thumb" /></a>
			// We need to verify this pattern does NOT exist near receipt thumbnails.

			// Check that there is no <a target="_blank"> immediately before an img with alt="thumb"
			const hasNewTabImageLink = /target="_blank"[^>]*>\s*<img[^>]*alt="thumb"/.test(pageContent);
			expect(hasNewTabImageLink).toBe(false);
		});

		it('should NOT have stopPropagation on the image cell', () => {
			// The image cell (<td>) must NOT stop click propagation, so the row's
			// openEditModal handler fires when the image is clicked.

			// Find all <td> elements that contain receipt_image_path (the image cell)
			// and check that none of them have stopPropagation in their opening tag.
			// We use a non-greedy match bounded by </td> to avoid crossing into other cells.
			const imageCells = pageContent.match(
				/<td[^>]*>(?:(?!<\/td>)[\s\S])*?receipt_image_path(?:(?!<\/td>)[\s\S])*?<\/td>/g
			);
			expect(imageCells).not.toBeNull();

			for (const cell of imageCells!) {
				// Extract just the opening <td> tag
				const openingTag = cell.match(/<td[^>]*>/);
				expect(openingTag).not.toBeNull();
				expect(openingTag![0]).not.toContain('stopPropagation');
			}
		});

		it('should render image thumbnail as a plain img (not wrapped in an anchor)', () => {
			// The receipt image thumbnail should be a plain <img> element, not wrapped
			// in an <a> tag. This way the row click handler opens the edit modal.

			// Check that there is no anchor tag with href containing storage URL wrapping alt="thumb"
			const hasAnchorWrappedThumb = /<a[^>]*href=\{[^}]*\}[^>]*>\s*<img[^>]*alt="thumb"/.test(
				pageContent
			);
			expect(hasAnchorWrappedThumb).toBe(false);
		});
	});

	describe('#{#ric1b} PDF Thumbnail Click Opens Edit Modal', () => {
		it('should NOT have target="_blank" links wrapping PDF thumbnails', () => {
			// PDF receipt links should not open in a new tab either.
			// The PDF icon/text should not be wrapped in <a target="_blank">

			// Look for the pattern: <a ... target="_blank" ...> near "PDF" text within the image cell
			// After implementation, PDF should be a plain <span> or similar, not an <a>
			const pdfSection = pageContent.match(/endsWith\('\.pdf'\)[\s\S]*?{:else}/);

			if (pdfSection) {
				const hasPdfNewTabLink = /target="_blank"/.test(pdfSection[0]);
				expect(hasPdfNewTabLink).toBe(false);
			}
		});

		it('should render PDF indicator without anchor tag navigation', () => {
			// The PDF indicator should not use an <a> tag that navigates away
			const pdfSection = pageContent.match(/endsWith\('\.pdf'\)[\s\S]*?{:else}/);

			if (pdfSection) {
				// Should not contain an <a> tag with href
				const hasAnchorTag = /<a\s[^>]*href=/.test(pdfSection[0]);
				expect(hasAnchorTag).toBe(false);
			}
		});
	});
});

