	async deleteAll(
		familyId: string,
		options?: {
			creditCardType?: CreditCardType;
			beforeDate?: string;
			afterDate?: string;
		}
	): Promise<number> {
		// Count matching transactions before deleting
		let countQuery = supabase
			.from('transactions')
			.select('id', { count: 'exact', head: true })
			.eq('family_id', familyId);

		if (options?.creditCardType) {
			countQuery = countQuery.eq('credit_card_type', options.creditCardType);
		}
		if (options?.afterDate) {
			countQuery = countQuery.gte('transaction_date', options.afterDate);
		}
		if (options?.beforeDate) {
			countQuery = countQuery.lt('transaction_date', options.beforeDate);
		}

		const { count } = await countQuery;

		// Delete with the same filters
		let deleteQuery = supabase.from('transactions').delete().eq('family_id', familyId);

		if (options?.creditCardType) {
			deleteQuery = deleteQuery.eq('credit_card_type', options.creditCardType);
		}
		if (options?.afterDate) {
			deleteQuery = deleteQuery.gte('transaction_date', options.afterDate);
		}
		if (options?.beforeDate) {
			deleteQuery = deleteQuery.lt('transaction_date', options.beforeDate);
		}

		const { error } = await deleteQuery;

		if (error) {
			throw new Error(`Failed to delete transactions: ${error.message}`);
		}

		return count || 0;
	}
}

