// #{#tbd1a} Bulk delete filtered transactions
async function deleteFiltered(): Promise<void> {
	if (!familyId || transactions.length === 0) return;

	const filters: { creditCardType?: string; dateFrom?: string; dateTo?: string } = {};
	if (filterCardType !== 'all') filters.creditCardType = filterCardType;
	if (filterCreditCardType !== 'all') filters.creditCardType = filterCreditCardType;
	if (urlDateFrom) filters.dateFrom = urlDateFrom;
	if (urlDateTo) filters.dateTo = urlDateTo;

	const msg = formatBulkDeleteMessage(transactions.length, filters);
	if (!confirm(msg)) return;

	bulkDeleting = true;
	error = null;
	try {
		const options: any = {};
		if (filters.creditCardType) options.creditCardType = filters.creditCardType;
		if (urlDateFrom) options.afterDate = urlDateFrom;
		if (urlDateTo) {
			// Add one day to make dateTo inclusive (deleteAll uses < for beforeDate)
			options.beforeDate = toExclusiveEndBoundary(urlDateTo);
		}

		const deleted = await TransactionService.get().deleteAll(familyId, options);
		successMessage = `${deleted} transaction${deleted !== 1 ? 's' : ''} deleted`;
		await loadTransactions();
	} catch (e: any) {
		error = e?.message ?? 'Failed to delete transactions';
	} finally {
		bulkDeleting = false;
	}
}

input.new_string:
// #{#tbd1a} Selection-based bulk delete — only the checked rows.
async function deleteSelected(): Promise<void> {
	const ids = Array.from(transactionSelection.selected);
	if (ids.length === 0) return;
	if (!confirm(`Delete ${ids.length} selected transaction${ids.length === 1 ? '' : 's'}?`)) {
		return;
	}

	bulkDeleting = true;
	error = null;
	const original = [...allTransactions];
	// Optimistic update — remove from UI immediately
	allTransactions = allTransactions.filter((t) => !transactionSelection.selected.has(t.id));

	try {
		await TransactionService.get().deleteByIds(ids);
		successMessage = `${ids.length} transaction${ids.length === 1 ? '' : 's'} deleted`;
		transactionSelection = emptySelection();
	} catch (e: any) {
		// Rollback on failure
		allTransactions = original;
		error = e?.message ?? 'Failed to delete transactions';
	} finally {
		bulkDeleting = false;
	}
}

